    vec2 b = cos(vec2(px, px + HALF_PI) + tSpeed2) * wob2;
    float cut = px + thickness;
    k.x = max(cut, length(p.yz - a) - thickness);
    k.y = max(cut, length(p.yz - b) - thickness);
    s = min(s, min(k.x, k.y));
    if (s < 0.001 || d > 300.0) break;
    d += s * 0.7;
  }
  vec3 raw = max(cos(d * TAU) - s * sqrt(d) - vec3(k, 0.0), 0.0);
  float field = max(raw.r, max(raw.g, raw.b));
  raw.gb += 0.1;
  raw = raw * 0.4 + raw.brg * 0.6 + raw * raw;
  float lum = dot(raw, vec3(0.299, 0.587, 0.114));
  float w1 = max(0.0, 1.0 - k.x * 2.0) + 0.0001;
  float w2 = max(0.0, 1.0 - k.y * 2.0) + 0.0001;
  vec3 base = (u[5].rgb * w1 + u[6].rgb * w2) / (w1 + w2);
  float soft = smoothstep(0.03, 0.36, field);
  float hot = smoothstep(0.32, 0.8, field);
  vec3 light = base * lum * 2.6 * soft + mix(base, vec3(1.0), 0.55) * hot * u[4].x * 2.0;
  return vec4(light, field);
}
#endif

#if defined(VIDEORC_PASS_COARSE)
void main() {
  outColor = traceLight(gl_FragCoord.xy * (u[1].xy / u[0].xy));
}
#elif defined(VIDEORC_PASS_FINE)
void main() {
  vec2 coarseSize = vec2(textureSize(t0, 0));
  vec2 uv = gl_FragCoord.xy / u[0].xy;
  vec2 pos = uv * coarseSize - 0.5;
  ivec2 cell = ivec2(floor(pos));
  ivec2 last = ivec2(coarseSize) - 1;
  float a = texelFetch(t0, clamp(cell, ivec2(0), last), 0).a;
  float b = texelFetch(t0, clamp(cell + ivec2(1, 0), ivec2(0), last), 0).a;
  float c = texelFetch(t0, clamp(cell + ivec2(0, 1), ivec2(0), last), 0).a;
  float d = texelFetch(t0, clamp(cell + ivec2(1, 1), ivec2(0), last), 0).a;
  float high = max(max(a, b), max(c, d));
  float low = min(min(a, b), min(c, d));
  if (high > 0.02 && low < 0.4) outColor = traceLight(gl_FragCoord.xy * (u[1].xy / u[0].xy));
  else outColor = texture(t0, uv);
}
#elif defined(VIDEORC_PASS_DOWN)
void main() {
  vec2 uv = gl_FragCoord.xy / u[0].xy;
  vec2 texel = 1.0 / vec2(textureSize(t0, 0));
  vec4 sum = texture(t0, uv) * 4.0;
  sum += texture(t0, uv - texel);
  sum += texture(t0, uv + texel);
  sum += texture(t0, uv + vec2(texel.x, -texel.y));
  sum += texture(t0, uv - vec2(texel.x, -texel.y));
  outColor = sum / 8.0;
}
#elif defined(VIDEORC_PASS_UP)
void main() {
  vec2 uv = gl_FragCoord.xy / u[0].xy;
  vec2 h = 0.5 / vec2(textureSize(t0, 0));
  vec4 sum = texture(t0, uv + vec2(-h.x * 2.0, 0.0));
  sum += texture(t0, uv + vec2(h.x * 2.0, 0.0));
  sum += texture(t0, uv + vec2(0.0, -h.y * 2.0));
  sum += texture(t0, uv + vec2(0.0, h.y * 2.0));
  sum += texture(t0, uv + vec2(-h.x, h.y)) * 2.0;
  sum += texture(t0, uv + h) * 2.0;
  sum += texture(t0, uv + vec2(h.x, -h.y)) * 2.0;
  sum += texture(t0, uv - h) * 2.0;
  outColor = sum / 12.0 + texture(t1, uv);
}
#else
float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

void main() {
  vec2 uv = gl_FragCoord.xy / u[0].xy;
  float exposure = u[4].y;
  vec3 hdr = texture(t0, uv).rgb * exposure;
  hdr += texture(t1, uv).rgb * exposure * u[4].z * 0.18;
  float grain = (hash(gl_FragCoord.xy + fract(u[0].z * 7.31) * 113.0) - 0.5) * u[4].w;
  vec3 mapped = 1.0 - exp(-hdr);
  float level = max(mapped.r, max(mapped.g, mapped.b));
  mapped = clamp(mapped + grain * level, 0.0, 1.0) * u[5].w;
  float alpha = max(mapped.r, max(mapped.g, mapped.b));
  outColor = vec4((mapped + u[8].rgb * (1.0 - alpha)) * (1.0 - u[1].z), 1.0);
}
#endif

shaders.main:
#version 300 es
// Liquid Chrome, from React Bits by David Haz (https://reactbits.dev, MIT +
// Commons Clause), used in Videorc with the author's permission. Adapted for
// Videorc (plan 190): the pointer ripple simulation, its slope pass, the tilt
// and the intro are gone (a recording has no pointer), dark mode only, drawn
// opaque over the look's base colour, and uniforms are packed into `u`
// (layout in live_background/mod.rs).
precision highp float;

uniform vec4 u[16];
out vec4 outColor;

float lamp(vec2 p, vec2 center, vec2 size, float soft) {
  vec2 grown = size + soft;
  vec2 q = (p - center) / grown;
  q *= q;
  float d = sqrt(sqrt(dot(q, q)));
  float edge = soft / min(grown.x, grown.y);
  float shape = (1.0 - smoothstep(1.0 - edge, 1.0 + edge, d)) * (1.0 - 0.45 * d * d);
  return shape * size.x * size.y / (grown.x * grown.y);
}

vec3 studio(vec3 r, float blur) {
  vec2 p = r.xy / max(r.z + 1.0, 0.05);
  p += u[5].xy * smoothstep(0.3, 1.0, length(p));
  float radius = length(p);
  float soft = 0.008 + blur;
  vec2 dir = p / max(radius, 1e-3);
  float key = lamp(p, vec2(-0.25, 0.42), vec2(0.3, 0.12), soft);
  float side = lamp(p, vec2(0.48, 0.12), vec2(0.06, 0.3), soft);
  float ground = lamp(p, vec2(-0.1, -0.55), vec2(0.45, 0.06), soft);
  float rise = smoothstep(-1.0, 1.0, dir.y);
  float width = 0.015 + soft * 2.0;
  float rim = exp(-abs(radius - 1.0) / width) * 0.031 / width * (0.8 + smoothstep(-0.5, 0.8, p.y));
  float band = 1.0 - 0.95 * smoothstep(1.04 - soft, 1.12 + soft, radius);
  float wall = smoothstep(1.25, 1.55, radius) * (0.6 + 0.4 * rise);
  float streak = smoothstep(0.2, 0.8, 0.5 + 0.5 * sin(atan(dir.y, dir.x) * 3.0 + 0.6));
  vec3 color = vec3(0.004, 0.004, 0.005) + 0.02 * smoothstep(-0.4, 0.6, p.y);
  color += vec3(1.0, 0.97, 0.94) * key * 4.0 + vec3(0.9, 0.95, 1.0) * side * 3.0 + ground * 1.2;
  color += vec3(1.0, 0.98, 0.95) * rim;
  color *= band;
  return color + vec3(mix(0.45, 1.8, streak)) * wall;
}

vec3 shade(vec2 slope, vec3 v, float blur, vec3 f0) {
  float steep = length(slope);
  slope *= 3.0 * tanh(steep / 3.0) / max(steep, 1e-6);
  vec3 n = normalize(vec3(-slope, 1.0));
  vec3 r = reflect(v, n);
  float facing = clamp(dot(n, -v), 0.0, 1.0);
  return studio(r, blur) * (f0 + (1.0 - f0) * pow(1.0 - facing, 5.0));
}

vec3 aces(vec3 x) {
  return clamp((x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14), 0.0, 1.0);
}

void main() {
  vec2 res = u[0].xy;
  float unit = min(res.x, res.y);
  float time = u[0].z;
  vec2 frag = gl_FragCoord.xy;
  vec2 uv = (2.0 * frag - res) / unit;
  vec2 p = uv;
  vec2 rowX = vec2(1.0, 0.0);
  vec2 rowY = vec2(0.0, 1.0);
  float presence = u[4].w;
  float amplitude = u[2].x * presence;
  vec2 frequency = u[2].yz;
  for (float i = 1.0; i < 9.0; i++) {
    if (i > u[2].w) break;
    float a = amplitude / i;
    float soften = exp(0.3 - 0.3 * i);
    float argX = i * frequency.x * p.y + time;
    p.x += a * cos(argX);
    rowX -= a * sin(argX) * i * frequency.x * soften * rowY;
    float argY = i * frequency.y * p.x + time;
    p.y += a * cos(argY);
    rowY -= a * sin(argY) * i * frequency.y * soften * rowX;
  }
  float phase = time - p.x - p.y;
  vec2 field = -(rowX + rowY);
  float density = max(length(field), 1e-3);
  vec2 across = field / density;
  float k = u[3].x;
  float sn = sin(phase);
  float cs = cos(phase);
  float th = tanh(k * sn);
  float bevel = (1.0 - th * th) / tanh(k);
  float fade = smoothstep(3.0, 9.0, 3.14159 * unit / density);
  float weight = u[3].y * presence * fade;
  vec2 slope = k * cs * bevel * weight * across;
  vec2 sweep = -k * bevel * (sn + 2.0 * k * cs * cs * th) * weight * density * 2.0 / unit * across;
  vec2 stepX = dFdx(slope);
  vec2 stepY = dFdy(slope);
  vec2 crease = dot(stepX, stepX) > dot(stepY, stepY) ? stepX : stepY;
  if (dot(crease, crease) > dot(sweep, sweep)) sweep = crease;
  float bend = length(sweep);
  float alpha = smoothstep(0.0, 0.1, length(slope));
  vec3 f0 = mix(vec3(1.0), u[4].rgb, smoothstep(0.05, 0.6, length(slope))) * 0.92;
  vec3 v = normalize(vec3(uv * 0.08, -1.0));
  float blur = u[3].z * 0.35;
  vec3 light;
  if (bend < 0.01) {
    light = shade(slope, v, blur + bend * 0.5, f0);
  } else {
    light = vec3(0.0);
    for (float t = -0.375; t < 0.4; t += 0.25) {
      light += shade(slope + sweep * t, v, blur + bend * 0.15, f0);
    }
    light *= 0.25;
  }
  vec3 color = pow(aces(light * u[3].w), vec3(1.0 / 2.2));
  float grain = fract(52.9829189 * fract(dot(frag, vec2(0.06711056, 0.00583715))));
  color += (grain - 0.5) / 255.0;
  vec3 premultiplied = clamp(color, 0.0, 1.0) * alpha;
  outColor = vec4((premultiplied + u[6].rgb * (1.0 - alpha)) * (1.0 - u[1].z), 1.0);
}

#version 300 es
// Line Waves, from React Bits by David Haz (https://reactbits.dev, MIT +
// Commons Clause), used in Videorc with the author's permission. Adapted for
// Videorc (plan 190): the mouse lens, click ripples and intro reveal are
// constants, dark mode only, drawn opaque over the look's base colour, and
// uniforms are packed into `u` (layout in live_background/mod.rs).
precision highp float;

uniform vec4 u[16];
out vec4 outColor;

vec2 rotate(vec2 p, float a) {
  float c = cos(a);
  float s = sin(a);
  return vec2(c * p.x - s * p.y, s * p.x + c * p.y);
}

float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = p - i;
  vec2 w = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), w.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), w.x), w.y);
}

float smootherstep(float edge0, float edge1, float x) {
  float t = clamp((x - edge0) / (edge1 - edge0), 0.0, 1.0);
  return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}

float bend(vec2 p, float t) {
  float scale = u[3].w;
  vec2 q = p * 2.0 / scale;
  float w = 0.6 * sin(q.x * 0.55 + t * 0.4 + 0.6 * sin(q.y * 0.9 - t * 0.28));
  w += 0.21 * sin(q.x * 1.3 - t * 0.33 + q.y * 0.8 + 1.3);
  w += 0.12 * sin(q.y * 2.3 + q.x * 0.9 - t * 0.37 + 0.4);
  return w * u[3].z * scale * 0.46;
}

float river(vec2 p, float y, float t) {
  float drift = 0.7 * (0.18 * sin(p.x * 1.6 - t * 0.33 + 0.7) + 0.1 * sin(p.x * 3.1 + t * 0.21));
  float center = 0.5 * (0.2 * sin(t * 0.17) + 0.08 * sin(t * 0.29 + 1.3));
  float width = 0.13 * u[3].y;
  float near = (y - center - drift) / width;
  float far = (y + 0.22 * sin(t * 0.13 + 2.0) - drift * 0.6 + 0.3) / (width * 0.55);
  return max(exp(-near * near), exp(-far * far) * 0.7);
}

vec3 palette(float x) {
  x = fract(x) * 3.0;
  if (x < 1.0) return mix(u[5].rgb, u[6].rgb, smoothstep(0.0, 1.0, x));
  if (x < 2.0) return mix(u[6].rgb, u[7].rgb, smoothstep(1.0, 2.0, x));
  return mix(u[7].rgb, u[5].rgb, smoothstep(2.0, 3.0, x));
}

void main() {
  vec2 res = u[0].xy;
  float aspect = res.x / res.y;
  vec2 uv = gl_FragCoord.xy / res;
  vec2 p = rotate((gl_FragCoord.xy - 0.5 * res) / res.y, u[4].x);
  float t = u[0].z;
  float pixel = u[0].w;
  float lines = u[2].x;
  float highlight = u[3].x;

  float w = bend(p, t);
  float y = p.y + w;
  float phi = y * lines;
  float fw = max(fwidth(phi), 1e-5);
  float crowd = smoothstep(0.18, 0.5, fw);

  float fold = smoothstep(1.3, 2.2, fw * res.y / lines);
  float shimmer = mix(1.0, smoothstep(0.15, 0.85, noise(vec2(y * 1.6 + t * 0.07, p.x * 0.55 - t * 0.22))), 0.5);
  float lit = max(river(p, y, t), fold * 0.9) * shimmer;
  float light = mix(1.0, 0.07 + 0.93 * lit, highlight);

  float dist = abs(fract(phi + 0.5) - 0.5) / fw;
  float width = u[2].y * pixel * (1.0 + 1.5 * lit * highlight);
  float cover = clamp(min(dist + width * 0.5, 0.5) - max(dist - width * 0.5, -0.5), 0.0, 1.0);
  cover = mix(cover, min(width * fw, 1.0), crowd);
  float halo = exp(-dist / (2.2 * pixel)) * (1.0 - crowd) * u[2].z;
  float threadShade = mix(1.0, 0.55 + 0.45 * hash(vec2(floor(phi + 0.5), 7.3)), 0.45 * (1.0 - crowd));

  // The intro reveal is finished (React Bits' uReveal = 1).
  float span = 0.5 * sqrt(aspect * aspect + 1.0);
  float sweep = span + 0.6;
  float reveal = 1.0 - smoothstep(sweep - 0.6, sweep, p.x);

  float edge = 1.0;
  float edgeFade = u[4].z;
  if (edgeFade > 0.0) {
    float ex = min(uv.x, 1.0 - uv.x) * aspect;
    float ey = min(uv.y, 1.0 - uv.y);
    edge = smootherstep(0.0, edgeFade * 0.5, ex) * smootherstep(0.0, edgeFade * 0.5, ey);
  }

  // React Bits' colour cycle advances at speed * cycleSpeed * 0.05 per second,
  // and its time at speed * 2.5: so cycle = time * cycleSpeed * 0.02.
  vec3 tint = palette(y * 0.3 + p.x * 0.2 + t * u[4].y * 0.02);
  float grain = (fract(52.9829189 * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715)))) - 0.5) / 255.0;

  float strength = (cover + halo) * threadShade * light * u[2].w * reveal * edge;
  vec3 color = clamp(tint * strength * u[4].w, 0.0, 1.0);
  float alpha = max(color.r, max(color.g, color.b));
  color = clamp(color + grain, 0.0, 1.0);
  vec3 premultiplied = min(color, vec3(alpha));
  outColor = vec4((premultiplied + u[8].rgb * (1.0 - alpha)) * (1.0 - u[1].z), 1.0);
}

shaders.composite:
#version 300 es
// Beams, from React Bits by David Haz (https://reactbits.dev, MIT + Commons
// Clause), used in Videorc with the author's permission. Adapted for Videorc
// (plan 194): the pointer and the intro are constants (N3), dark mode only,
// drawn opaque over the look's base colour, the grain fixed in place, and
// uniforms are packed into `u` (layout in live_background/mod.rs).
//
// Passes: VIDEORC_PASS_FIELD renders the glint field at three quarters of the
// view (sizes::beams_field_size, then mipmaps); the default pass composites
// it from t0's mip chain.
//
// u[2] = (beam width, wave length, depth, roughness); the first two in CSS px
// u[3] = (cos rotation, sin rotation, twist, fill light)
// u[4] = (variation seed, gain, glow, grain)
// u[5] = tint (linear)
// u[6] = base colour
precision highp float;

uniform vec4 u[16];
uniform sampler2D t0;
out vec4 outColor;

const float PI = 3.141592653589793;

#ifdef VIDEORC_PASS_FIELD
vec4 permute(vec4 x) {
  return mod(((x * 34.0) + 1.0) * x, 289.0);
}

vec4 taylorInvSqrt(vec4 r) {
  return 1.79284291400159 - 0.85373472095314 * r;
}

vec3 fade(vec3 t) {
  return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}

float cnoise(vec3 P) {
  vec3 Pi0 = floor(P);
  vec3 Pi1 = Pi0 + vec3(1.0);
  Pi0 = mod(Pi0, 289.0);
  Pi1 = mod(Pi1, 289.0);
  vec3 Pf0 = fract(P);
  vec3 Pf1 = Pf0 - vec3(1.0);
  vec4 ix = vec4(Pi0.x, Pi1.x, Pi0.x, Pi1.x);
  vec4 iy = vec4(Pi0.yy, Pi1.yy);
  vec4 iz0 = Pi0.zzzz;
  vec4 iz1 = Pi1.zzzz;
  vec4 ixy = permute(permute(ix) + iy);
  vec4 ixy0 = permute(ixy + iz0);
  vec4 ixy1 = permute(ixy + iz1);
  vec4 gx0 = ixy0 / 7.0;
  vec4 gy0 = fract(floor(gx0) / 7.0) - 0.5;
  gx0 = fract(gx0);
  vec4 gz0 = vec4(0.5) - abs(gx0) - abs(gy0);
  vec4 sz0 = step(gz0, vec4(0.0));
  gx0 -= sz0 * (step(0.0, gx0) - 0.5);
  gy0 -= sz0 * (step(0.0, gy0) - 0.5);
  vec4 gx1 = ixy1 / 7.0;
  vec4 gy1 = fract(floor(gx1) / 7.0) - 0.5;
  gx1 = fract(gx1);
  vec4 gz1 = vec4(0.5) - abs(gx1) - abs(gy1);
  vec4 sz1 = step(gz1, vec4(0.0));
  gx1 -= sz1 * (step(0.0, gx1) - 0.5);
  gy1 -= sz1 * (step(0.0, gy1) - 0.5);
  vec3 g000 = vec3(gx0.x, gy0.x, gz0.x);
  vec3 g100 = vec3(gx0.y, gy0.y, gz0.y);
  vec3 g010 = vec3(gx0.z, gy0.z, gz0.z);
  vec3 g110 = vec3(gx0.w, gy0.w, gz0.w);
  vec3 g001 = vec3(gx1.x, gy1.x, gz1.x);
  vec3 g101 = vec3(gx1.y, gy1.y, gz1.y);
  vec3 g011 = vec3(gx1.z, gy1.z, gz1.z);
  vec3 g111 = vec3(gx1.w, gy1.w, gz1.w);
  vec4 norm0 = taylorInvSqrt(vec4(dot(g000, g000), dot(g010, g010), dot(g100, g100), dot(g110, g110)));
  g000 *= norm0.x;
  g010 *= norm0.y;
  g100 *= norm0.z;
  g110 *= norm0.w;
  vec4 norm1 = taylorInvSqrt(vec4(dot(g001, g001), dot(g011, g011), dot(g101, g101), dot(g111, g111)));
  g001 *= norm1.x;
  g011 *= norm1.y;
  g101 *= norm1.z;
  g111 *= norm1.w;
  float n000 = dot(g000, Pf0);
  float n100 = dot(g100, vec3(Pf1.x, Pf0.yz));
  float n010 = dot(g010, vec3(Pf0.x, Pf1.y, Pf0.z));
  float n110 = dot(g110, vec3(Pf1.xy, Pf0.z));
  float n001 = dot(g001, vec3(Pf0.xy, Pf1.z));
  float n101 = dot(g101, vec3(Pf1.x, Pf0.y, Pf1.z));
  float n011 = dot(g011, vec3(Pf0.x, Pf1.yz));
  float n111 = dot(g111, Pf1);
  vec3 fade_xyz = fade(Pf0);
  vec4 n_z = mix(vec4(n000, n100, n010, n110), vec4(n001, n101, n011, n111), fade_xyz.z);
  vec2 n_yz = mix(n_z.xy, n_z.zw, fade_xyz.y);
  float n_xyz = mix(n_yz.x, n_yz.y, fade_xyz.x);
  return 2.2 * n_xyz;
}

float laneHash(float lane) {
  return fract(sin(lane * 91.3458 + u[4].x * 17.17) * 47453.5453);
}

float lobe(float nh, float nl, float nv, float vh, float roughness) {
  float a = roughness * roughness;
  float a2 = a * a;
  float d = nh * nh * (a2 - 1.0) + 1.0;
  float distribution = a2 / (PI * d * d);
  float gv = nl * sqrt(nv * nv * (1.0 - a2) + a2);
  float gl = nv * sqrt(nl * nl * (1.0 - a2) + a2);
  float visibility = 0.5 / max(gv + gl, 0.0001);
  float fresnel = 0.028 + 0.972 * pow(1.0 - vh, 5.0);
  return distribution * visibility * fresnel * nl;
}

vec2 glint(float lane, vec2 local, float uTime, float camera) {
  float along = local.y / u[2].y - laneHash(lane) * 60.0;
  float step = 0.01;
  float slope = (cnoise(vec3(0.0, along + step, uTime)) - cnoise(vec3(0.0, along - step, uTime))) / (2.0 * step);
  slope *= 0.2 * u[2].z;
  float spin = laneHash(lane + 0.37);
  float tilt = ((spin - 0.5) * 0.5 + sin(uTime * 2.1 + spin * 6.2831) * 0.06) * u[3].z;
  vec3 normal = normalize(vec3(tilt, -slope, 1.0));
  vec3 view = normalize(vec3(-local, camera));
  float nv = max(dot(normal, view), 0.0001);
  // The light rests at React Bits' (0, 3, 10): the intro sweep is over and
  // the pointer never lifts it.
  vec3 light = normalize(vec3(0.0, 3.0, 10.0));
  vec3 halfway = normalize(light + view);
  float roughness = u[2].w;
  float core = lobe(max(dot(normal, halfway), 0.0), max(dot(normal, light), 0.0), nv, max(dot(view, halfway), 0.0), roughness);
  vec3 fill = normalize(vec3(0.0, -3.0 * 1.25, 10.0));
  vec3 fillHalf = normalize(fill + view);
  core += u[3].w * lobe(max(dot(normal, fillHalf), 0.0), max(dot(normal, fill), 0.0), nv, max(dot(view, fillHalf), 0.0), roughness);
  return vec2(core, core);
}

void main() {
  // React Bits sizes the beams in CSS pixels; one is min(view) / 1080 render
  // pixels, so uScale is CSS pixels per field texel.
  vec2 viewCss = u[1].xy / u[0].w;
  vec2 uScale = viewCss / u[0].xy;
  vec2 css = gl_FragCoord.xy * uScale;
  vec2 centered = css - viewCss * 0.5;
  vec2 local = mat2(u[3].x, -u[3].y, u[3].y, u[3].x) * centered;
  float uTime = mod(u[0].z * 0.12, 289.0);
  float camera = viewCss.y * 1.866;

  float across = local.x / u[2].x + 0.5;
  float lane = floor(across);
  float along = across - lane;
  vec2 value = glint(lane, local, uTime, camera);

  float pixel = max(uScale.x, uScale.y);
  float seam = min(along, 1.0 - along) * u[2].x;
  if (seam < pixel * 1.5) {
    float other = along < 0.5 ? lane - 1.0 : lane + 1.0;
    float blend = 0.5 * (1.0 - smoothstep(0.0, pixel * 1.5, seam));
    value = mix(value, glint(other, local, uTime, camera), blend);
  }

  // The pointer rests (React Bits' uPointer.z = 0), so nothing brightens
  // near it.
  float hot = max(value.y - 0.18, 0.0);
  outColor = vec4(value.x, value.y, min(hot, 6.0), 1.0);
}
#else
float random(vec2 st) {
  return fract(sin(dot(st, vec2(12.9898, 78.233))) * 43758.5453123);
}

float grainNoise(vec2 st) {
  vec2 i = floor(st);
  vec2 f = fract(st);
  float a = random(i);
  float b = random(i + vec2(1.0, 0.0));
  float c = random(i + vec2(0.0, 1.0));
  float d = random(i + vec2(1.0, 1.0));
  vec2 w = f * f * (3.0 - 2.0 * f);
  return mix(a, b, w.x) + (c - a) * w.y * (1.0 - w.x) + (d - b) * w.x * w.y;
}

vec3 acesFilmic(vec3 color) {
  const mat3 inputMatrix = mat3(
    vec3(0.59719, 0.07600, 0.02840),
    vec3(0.35458, 0.90834, 0.13383),
    vec3(0.04823, 0.01566, 0.83777)
  );
  const mat3 outputMatrix = mat3(
    vec3(1.60475, -0.10208, -0.00327),
    vec3(-0.53108, 1.10813, -0.07276),
    vec3(-0.07367, -0.00605, 1.07602)
  );
  color = inputMatrix * (color / 0.6);
  vec3 a = color * (color + 0.0245786) - 0.000090537;
  vec3 b = color * (0.983729 * color + 0.4329510) + 0.238081;
  color = outputMatrix * (a / b);
  return clamp(color, 0.0, 1.0);
}

vec3 toSrgb(vec3 color) {
  return mix(color * 12.92, 1.055 * pow(color, vec3(1.0 / 2.4)) - 0.055, step(vec3(0.0031308), color));
}

void main() {
  vec2 uv = gl_FragCoord.xy / u[0].xy;
  float radiance = textureLod(t0, uv, 0.0).r;
  float bloom = 0.0;
  bloom += textureLod(t0, uv, 2.0).b * 0.3;
  bloom += textureLod(t0, uv, 3.0).b * 0.3;
  bloom += textureLod(t0, uv, 4.0).b * 0.22;
  bloom += textureLod(t0, uv, 5.0).b * 0.18;

  float hot = textureLod(t0, uv, 0.0).g;
  vec3 tint = u[5].rgb;
  float gain = u[4].y;
  vec3 light = tint * (radiance + bloom * u[4].z) * gain;
  light += mix(tint, vec3(1.0), 0.7) * hot * hot * 0.12 * gain;
  // The intro is finished (React Bits' uPresence = 1).
  vec3 color = toSrgb(acesFilmic(light));
  color -= grainNoise(gl_FragCoord.xy) / 15.0 * u[4].w;
  color = max(color, 0.0);

  // No edge fade and full opacity: React Bits' mask is 1.
  float dither = (random(gl_FragCoord.yx + 31.7) - 0.5) / 255.0;
  color = clamp(color + dither, 0.0, 1.0);
  float alpha = max(color.r, max(color.g, color.b));
  outColor = vec4((color + u[6].rgb * (1.0 - alpha)) * (1.0 - u[1].z), 1.0);
}
#endif

