void main() {
  vec2 cell = floor(gl_FragCoord.xy / cellSize());
  ivec2 fieldSize = textureSize(t0, 0);
  vec4 sampleValue = texelFetch(t0, clamp(ivec2(cell), ivec2(0), fieldSize - 1), 0);
  float f = sampleValue.r + sampleValue.g / 255.0;
