    vec2 b1 = bound(camera.xy + rd.xy * tb, origin);
    float b = max(b0.x, b1.x) + 0.03;
    float z1 = camera.z + rd.z * tb;
    if (z1 > b) {
      ta = tb;
      b0 = b1;
